INSERT INTO `tb_wa_log` VALUES (1,'peringatan_dini',1989,'6285358082133','Pengingat: pengajuan \"Perjalanan Dinas Kegiatan Audit Sarana dalam rangka Sertifikasi Sistem Manajemen Keamanan Pangan Olahan (SMKPO) di Kab. Bangka Tengah selama 1 (satu) hari pada Tanggal 10 Agustus 2026\" sudah berjalan 16 hari kerja dan tertahan 11 HK di tahap PPK. Target cair sebelum 17/08/2026. Mohon segera ditindaklanjuti.',200,'ok','{\"status\":true,\"message\":\"Text Message is pending and waiting to be processed\",\"data\":{\"device_id\":\"IYGC9S\",\"quota\":\"unlimited\",\"messages\":[{\"id\":\"28321677-ae77-413c-9984-e7616aae8a9f\",\"phone\":\"6285358082133\",\"message\":\"???? Notifikasi ASIKKEKKU\\n\\nPengingat: pengajuan \\\"Perjalanan Dinas Kegiatan Audit Sarana dalam rangka Sertifikasi Sistem Manajemen Keamanan Pangan Olahan (SMKPO) di Kab. Bangka Tengah selama 1 (satu) hari pada Tanggal 10 Agustus 2026\\\" sudah berjalan 16 hari kerja dan tertahan 11 HK di tahap PPK. Target cair sebelum 17\\/08\\/2026. Mohon segera ditindaklanjuti.\\n\\nRgds,\\nASIKKEKKU - Balai Besar POM di Pangkal Pinang\\n⛔ Pesan otomatis ini dikirim oleh sistem, mohon untuk tidak membalas.\",\"status\":\"pending\",\"ref_id\":\"\"}]}}','2026-09-02 15:57:56'),(2,'peringatan_dini',1989,'6285692412235','Update pengajuan \"Perjalanan Dinas Kegiatan Audit Sarana dalam rangka Sertifikasi Sistem Manajemen Keamanan Pangan Olahan (SMKPO) di Kab. Bangka Tengah selama 1 (satu) hari pada Tanggal 10 Agustus 2026\": masih diproses (hari kerja ke-16, tahap PPK). Sudah melewati target 4 hari kerja, sedang dikawal petugas.',200,'ok','{\"status\":true,\"message\":\"Text Message is pending and waiting to be processed\",\"data\":{\"device_id\":\"IYGC9S\",\"quota\":\"unlimited\",\"messages\":[{\"id\":\"b525e02c-32c7-4e5a-b385-acabe7995569\",\"phone\":\"6285692412235\",\"message\":\"???? Notifikasi ASIKKEKKU\\n\\nUpdate pengajuan \\\"Perjalanan Dinas Kegiatan Audit Sarana dalam rangka Sertifikasi Sistem Manajemen Keamanan Pangan Olahan (SMKPO) di Kab. Bangka Tengah selama 1 (satu) hari pada Tanggal 10 Agustus 2026\\\": masih diproses (hari kerja ke-16, tahap PPK). Sudah melewati target 4 hari kerja, sedang dikawal petugas.\\n\\nRgds,\\nASIKKEKKU - Balai Besar POM di Pangkal Pinang\\n⛔ Pesan otomatis ini dikirim oleh sistem, mohon untuk tidak membalas.\",\"status\":\"pending\",\"ref_id\":\"\"}]}}','2026-09-02 15:57:57');
